package com.vandorlabs.client;

import com.vandorlabs.tiles.*;
import net.minecraft.nbt.NBTTagCompound;

/** Previous-save defaults and independent finishes exercise the real tile serializers. */
final class FrameAppearanceRuntimeChecks {
    private static boolean done;
    static void run(){if(done)return;done=true;
        int frames=0,lit=0;for(int i=0;i<ScreenHousingTextures.IDS.length;i++)if("Frame".equals(ScreenHousingTextures.category(i))){frames++;require(!HousingTextureList.generalTexture(i),"frame leaked into ordinary material picker");FrameAppearance a=new FrameAppearance();a.front=i;if(a.light()>0)lit++;require(a.rail("").length()>0,"missing rail texture");require(!net.minecraft.client.Minecraft.getMinecraft().getTextureMapBlocks().getAtlasSprite(a.rail("")).getIconName().contains("missingno"),"unstitched packaged frame rail");}
        require(frames==70&&lit>0,"frame catalog coverage");
        TileEntityProgrammableGlass glass=new TileEntityProgrammableGlass();glass.readFromNBT(new NBTTagCompound());require(glass.frameAppearance.front==-1&&glass.frameAppearance.interior==-1,"old glass changes appearance");
        int bolted=ScreenHousingTextures.screenIndex("frames/frames-screen-full/frame_bolted_1254");require(bolted>0,"missing legacy bolted frame");
        TileEntityAnimatedScreenSelector bare=new TileEntityAnimatedScreenSelector();NBTTagCompound unchanged=bare.writeToNBT(new NBTTagCompound());bare.readFromNBT(unchanged);require(bare.frameAppearance.front==-1&&bare.isFramed(),"bare artwork flag on plain programmable blocks invented a frame");
        TileEntityAnimatedScreenSelector screen=new TileEntityAnimatedScreenSelector();NBTTagCompound old=screen.writeToNBT(new NBTTagCompound());old.removeTag("FrameFront");old.setBoolean("framed",true);for(com.vandorlabs.blocks.ModBlocks.ScreenOption option:com.vandorlabs.blocks.ModBlocks.SCREEN_OPTIONS)if(option.hasPair()){old.setString("selectedScreen",option.framedId);break;}screen.readFromNBT(old);require(!screen.isFramed()&&screen.frameAppearance.front==bolted,"previous-release framed display migration");
        NBTTagCompound opaque=new NBTTagCompound();opaque.setInteger("previous_release_opaque",91);old.setTag("ForgeCaps",opaque);com.vandorlabs.vehicle.VehicleStructure.Cell migrated=new com.vandorlabs.vehicle.VehicleStructure.Cell(net.minecraft.util.math.BlockPos.ORIGIN,com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR.getDefaultState(),old);require(migrated.tileData().getInteger("FrameFront")==bolted&&migrated.tileData().getCompoundTag("ForgeCaps").equals(opaque),"previous framed snapshot migration lost opaque capability data");

        NBTTagCompound engineering=new TileEntityAnimatedScreenSelector().writeToNBT(new NBTTagCompound());
        com.vandorlabs.vehicle.VehicleStructure.Cell oldEngineering=new com.vandorlabs.vehicle.VehicleStructure.Cell(net.minecraft.util.math.BlockPos.ORIGIN,com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR.getDefaultState(),engineering);
        require(oldEngineering.tileData().getInteger("FrameFront")==bolted&&oldEngineering.tileData().getInteger("DisplayArtworkVersion")==1,"old engineering snapshot default frame");
        com.vandorlabs.vehicle.VehicleStructure.Cell plain=new com.vandorlabs.vehicle.VehicleStructure.Cell(net.minecraft.util.math.BlockPos.ORIGIN,com.vandorlabs.blocks.ModBlocks.PROGRAMMABLE_BLOCK.getDefaultState(),engineering);require(!plain.tileData().hasKey("FrameFront")&&!plain.tileData().hasKey("DisplayArtworkVersion"),"plain block acquired engineering display defaults");
        NBTTagCompound overridden=engineering.copy();overridden.setInteger("PrimarySurfaceTexture",0);FrameAppearance.initializeDisplay(com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR,overridden);require(overridden.getInteger("FrameFront")==-1,"material override acquired engineering frame");
        for(int sentinel:new int[]{-2,-3}){NBTTagCompound special=engineering.copy();special.setInteger("PrimarySurfaceTexture",sentinel);FrameAppearance.initializeDisplay(com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR,special);require(special.getInteger("FrameFront")==-1,"Redstone/Vehicle Status override acquired engineering frame");}
        for(net.minecraft.block.Block block:new net.minecraft.block.Block[]{com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR,com.vandorlabs.blocks.ModBlocks.PROGRAMMABLE_FULL_INPUT,com.vandorlabs.blocks.ModBlocks.PROGRAMMABLE_CONSOLE,com.vandorlabs.blocks.ModBlocks.PROGRAMMABLE_DIAGONAL_SCREEN}){TileEntityAnimatedScreenSelector fresh=(TileEntityAnimatedScreenSelector)block.createTileEntity(null,block.getDefaultState());require(fresh.frameAppearance.front==bolted&&fresh.frameAppearance.artworkVersion==1,"fresh display factory frame default");}
        FrameAppearance original=new FrameAppearance();original.artworkVersion=1;NBTTagCompound picked=new NBTTagCompound();original.write(picked);picked.setString("selectedScreen","engineering_screen");require(!FrameAppearance.initializeDisplay(com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR,picked)&&picked.getInteger("FrameFront")==-1,"picked Original frame reset to bolted");
        TileEntityAnimatedScreenSelector freshOriginal=(TileEntityAnimatedScreenSelector)com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR.createTileEntity(null,com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR.getDefaultState());NBTTagCompound factory=freshOriginal.writeToNBT(new NBTTagCompound());factory.merge(picked);freshOriginal.readFromNBT(factory);freshOriginal.initializeDisplayArtwork(com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR);require(freshOriginal.frameAppearance.front==-1,"vanilla ItemBlock merge restored the factory frame over Original selection");
        for(String id:new String[]{"analysis_framed_gas_giant","analysis_framed_ice_planet","analysis_framed_surface_map","analysis_framed_terrestrial"}){
            require(TileEntityAnimatedScreenSelector.isValidInputPanel(id),"legacy analysis input fixture exists");NBTTagCompound legacy=new TileEntityAnimatedScreenSelector().writeToNBT(new NBTTagCompound());legacy.setString("inputPanel",id);TileEntityAnimatedScreenSelector input=new TileEntityAnimatedScreenSelector();input.readFromNBT(legacy);require(input.getInputPanel().equals(id)&&input.frameAppearance.front==bolted,"unpaired previous-release input artwork was replaced");
            int legacyChoice=com.vandorlabs.tiles.ScreenHousingTextures.screenIndex("console_inputs/"+id+"_static");require(legacyChoice>0,"legacy unified analysis artwork exists");NBTTagCompound surface=new NBTTagCompound();surface.setInteger("PrimarySurfaceTexture",legacyChoice);require(FrameAppearance.migrateLegacyScreen(surface)&&surface.getInteger("PrimarySurfaceTexture")==legacyChoice&&surface.getInteger("FrameFront")==bolted,"unpaired unified artwork migration lost its source or frame");
            input.frameAppearance.artworkVersion=1;input.frameAppearance.front=-1;TileEntityAnimatedScreenSelector originalInput=new TileEntityAnimatedScreenSelector();originalInput.readFromNBT(input.writeToNBT(new NBTTagCompound()));require(originalInput.getInputPanel().equals(id)&&originalInput.frameAppearance.front==-1,"unpaired input Original frame selection did not persist");
        }
        HousingTextureList splitPicker=HousingTextureList.forCategory("Screens",0,0,160,0);try{java.lang.reflect.Field f=HousingTextureList.class.getDeclaredField("options");f.setAccessible(true);for(Object row:((java.util.Map<?,?>)f.get(splitPicker)).values()){HousingTextureList.Option option=(HousingTextureList.Option)row;require(FrameAppearance.bareChoice(option.choice)==option.choice,"paired framed artwork leaked into split selector");}}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}
        screen.frameAppearance.interior=bolted;screen.frameAppearance.split=true;screen.frameAppearance.splitTop=0;screen.frameAppearance.splitBottom=1;screen.frameAppearance.displayFit=true;
        TileEntityAnimatedScreenSelector copy=new TileEntityAnimatedScreenSelector();copy.readFromNBT(screen.writeToNBT(new NBTTagCompound()));require(copy.frameAppearance.front==bolted&&copy.frameAppearance.interior==bolted&&copy.frameAppearance.split&&copy.frameAppearance.splitTop==0&&copy.frameAppearance.splitBottom==1&&copy.frameAppearance.displayFit,"frame/split tile persistence");
        com.vandorlabs.network.MessageFrameAppearance packet=new com.vandorlabs.network.MessageFrameAppearance(screen,screen.frameAppearance);io.netty.buffer.ByteBuf bytes=io.netty.buffer.Unpooled.buffer();packet.toBytes(bytes);require(bytes.readableBytes()==27,"fixed frame packet size");com.vandorlabs.network.MessageFrameAppearance decoded=new com.vandorlabs.network.MessageFrameAppearance();decoded.fromBytes(bytes);io.netty.buffer.ByteBuf round=io.netty.buffer.Unpooled.buffer();decoded.toBytes(round);bytes.readerIndex(0);require(bytes.equals(round),"frame packet roundtrip");bytes.release();round.release();
        for(com.vandorlabs.render.ScreenSurface.Kind kind:com.vandorlabs.render.ScreenSurface.Kind.values()){com.vandorlabs.render.ScreenSurface.Quad full=com.vandorlabs.render.ScreenSurface.quad(kind,false),top=com.vandorlabs.render.ScreenSurface.half(full,true),bottom=com.vandorlabs.render.ScreenSurface.half(full,false);require(top.bottomLeft.y==bottom.topLeft.y&&top.bottomLeft.z==bottom.topLeft.z,"split display gap");require(top==com.vandorlabs.render.ScreenSurface.half(full,true),"split geometry allocates repeatedly");}
        System.out.println("[vandorlabs][reprolab] configurable-frames PASS frames="+frames+" lit="+lit+" legacy-NBT split-NBT fixed-packet split-geometry");
    }
    private static void require(boolean condition,String message){if(!condition)throw new IllegalStateException(message);}
}
